"""The C generated by tools/transliterate.py against the original, its song variants,
semantics-preserving permutations of its code and a relocation."""

import json
import re
import time

import pytest

from support import (
    ASM,
    BUILD,
    ROOT,
    STOP_FRAMES,
    VARIANTS,
    assemble,
    gen_prg,
    patched,
    player_size,
)
import mutate
import sidtrace
import transliterate

PERMUTATIONS = json.loads((ROOT / "permutations.json").read_text(encoding="utf-8"))
PERMUTATIONS["all"] = sum(PERMUTATIONS.values(), [])
RELOCATE = [["ADDR    = $1000", "ADDR    = $2345"]]


@pytest.fixture(scope="module", name="generated")
def fixture_generated(ref_psid):
    """(.c, .h, info, seconds) of the original."""
    start = time.perf_counter()
    c, h, info = transliterate.transliterate(ref_psid, "commando.h")
    return c, h, info, time.perf_counter() - start


@pytest.fixture(scope="module", name="wrap")
def fixture_wrap(ref_psid, labels):
    """Frames to the tune loop."""
    return sidtrace.loop_frame(ref_psid, labels["posoff"], 50_000)


def _permuted(perm, out_dir, extra=()):
    """(PSID, labels) of the original source with permutation `perm` and `extra` edits."""
    edits = (PERMUTATIONS[perm] if perm else []) + list(extra)
    return assemble(mutate.apply(ASM.read_text(encoding="ascii"), edits), out_dir)


def _plain(perm, psid, generated):
    """(.c, .h) generated from the unpatched `psid` of permutation `perm`."""
    return (
        generated[:2]
        if perm is None
        else transliterate.transliterate(psid, "commando.h")[:2]
    )


def test_whole_tune_identical(capsys):
    """The `make` build of the generated C matches the original up to the tune loop."""
    args = [str(BUILD / n) for n in ("ref.sid", "gen.prg")]
    assert sidtrace.main(args + ["--wrap", str(BUILD / "ref.labels"), "posoff"]) == 0
    assert "OK" in capsys.readouterr().out


def test_generated_shape(generated):
    """Structured C without goto, under twice the playroutine source, quickly made."""
    c, _, _, seconds = generated
    assert not re.search(r"\bgoto\b", c)
    assert len(c.encode()) < 2 * player_size()
    assert seconds < 10


def test_main(tmp_path, capsys, generated):
    """The CLI writes the .c and its header."""
    out = tmp_path / "commando.c"
    args = [str(BUILD / "ref.sid"), str(out), "--header", str(tmp_path / "commando.h")]
    assert transliterate.main(args) == 0
    assert out.read_text(encoding="utf-8") == generated[0]
    assert (tmp_path / "commando.h").read_text(encoding="utf-8") == generated[1]
    assert "traps" in capsys.readouterr().out


@pytest.mark.slow
@pytest.mark.parametrize("variant", [None, *sorted(VARIANTS)])
@pytest.mark.parametrize("perm", [None, *sorted(PERMUTATIONS)])
def test_generated_identical(  # pylint: disable=too-many-arguments,too-many-positional-arguments
    perm, variant, ref_psid, labels, generated, wrap, tmp_path
):
    """Song variants change only the .h; permuted and generated code keep every write."""
    psid, perm_labels = _permuted(perm, tmp_path) if perm else (ref_psid, labels)
    plain = _plain(perm, psid, generated)
    frames = wrap
    if variant:
        ref_psid = patched(ref_psid, labels, VARIANTS[variant])
        psid = patched(psid, perm_labels, VARIANTS[variant])
        frames = STOP_FRAMES
    ref = sidtrace.trace_psid(ref_psid, frames)
    assert sidtrace.diff(ref, sidtrace.trace_psid(psid, frames)) is None
    prg, c, h = gen_prg(psid, tmp_path)
    assert c == plain[0]
    assert (h != plain[1]) == bool(variant)
    assert sidtrace.diff(ref, sidtrace.trace_prg(prg, frames)) is None


@pytest.mark.slow
@pytest.mark.parametrize("perm", [None, "all"])
def test_relocated(perm, generated, tmp_path):
    """Assembled at another address the .c is unchanged and the writes identical."""
    plain = _plain(perm, _permuted(perm, tmp_path)[0], generated)
    psid, labels = _permuted(perm, tmp_path, RELOCATE)
    assert sidtrace.psid_parts(psid)[0] == 0x2345
    prg, c, _ = gen_prg(psid, tmp_path)
    assert c == plain[0]
    frames = sidtrace.loop_frame(psid, labels["posoff"], 50_000)
    ref = sidtrace.trace_psid(psid, frames)
    assert sidtrace.diff(ref, sidtrace.trace_prg(prg, frames)) is None
